  const [copied, setCopied] = useState(false);

  const mutation = useMutation({
    mutationFn: () => createShareLink(ideaId),
    onSuccess: (data) => {
      const fullUrl = `${window.location.origin}${data.share_url}`;
      setShareUrl(fullUrl);
      toast.success("Share link created");
