            variant="outline"
            size="sm"
          >
            {mutation.isPending ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <Share2 className="mr-2 h-4 w-4" />
            )}
            Generate Share Link
          </Button>
        )}
      </CardContent>
    </Card>
  );
}

